 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, add, sub, mul, fract, sin, dot, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SRGBColorSpace } = ctx.THREE;

  const root = new Group();

  const specColors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const atlas = config.atlasRegion ?? { atlas: 0, x: 0, y: 0, width: 512, height: 320 };

  // --- Stage: engineered gradient backdrop with subtle film grain ---
  const inkNode = color(specColors.ink);
  const surfaceNode = color(specColors.surface);
  const vGrad = mix(surfaceNode, inkNode, smoothstep(0, 1, uv().y));

  const suv = uv();
  const noise = fract(
    sin(dot(suv, vec2(12.9898, 78.233))) * 43758.5453
  );
  const grain = sub(mul(noise, 0.035), 0.0175);
  const backdropColor = add(vGrad, vec3(grain));

  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ colorNode: backdropColor });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // --- Sprite: atlas-sliced plane that billboards toward the camera ---
  const regionW = atlas.width;
  const regionH = atlas.height;
  const aspect = regionW / regionH;

  const spriteGeo = new PlaneGeometry(aspect, 1);
  const spriteMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const sprite = new Mesh(spriteGeo, spriteMat);
  root.add(sprite);

  const timelines = [];

  const texUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl ?? '/prism-mock/home/nodes/floating-accent.png';

  if (texUrl) {
    ctx.textureLoader.loadTexture(texUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;

      const imgW = tex.image?.width ?? regionW;
      const imgH = tex.image?.height ?? regionH;

      // Source rect is given in top-left pixel coordinates.
      tex.offset.set(atlas.x / imgW, (imgH - atlas.y - atlas.height) / imgH);
      tex.repeat.set(atlas.width / imgW, atlas.height / imgH);
      tex.needsUpdate = true;

      spriteMat.map = tex;
      spriteMat.needsUpdate = true;

      // Weighted entrance + slow idle drift (the only motion; pure sprite, no primitives)
      gsap.fromTo(sprite.scale, { x: 0.92, y: 0.92 }, { x: 1, y: 1, duration: 0.8, ease: 'power3.out' });
      const idle = gsap.to(sprite.position, { y: 0.04, duration: 3.6, yoyo: true, repeat: -1, ease: 'sine.inOut' });
      timelines.push(idle);
    });
  }

  root.userData.handlers = {
    update: (time, camera) => {
      if (camera) sprite.quaternion.copy(camera.quaternion);
    }
  };

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    if (spriteMat.map && spriteMat.map.dispose) spriteMat.map.dispose();
    spriteMat.dispose();
    spriteGeo.dispose();
    backdropMat.dispose();
    backdropGeo.dispose();
  };

  return root;
}
